// Harness for the xz/liblzma multithreaded decoder progress race fixed by
// c6e3aadbb510e44cecfe870408ecfea1d1ca792c. The input is an .xz file; the
// race needs a threaded decoder, several blocks, and block headers that store
// both compressed and uncompressed sizes.
//
// Usage: ./xz-mt-decoder <threads> <file.xz>
//
//   <threads>  decoder worker count, for example 1 or 4
//   <file.xz>  compressed input generated by ../make-inputs.sh
//
// Trigger: ./xz-mt-decoder 4 ../inputs/multi-4KiB.xz
// Escape:  ./xz-mt-decoder 1 ../inputs/multi-4KiB.xz
#include <errno.h>
#include <inttypes.h>
#include <lzma.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int decode(FILE *in, uint32_t threads) {
  uint8_t inbuf[8192];
  uint8_t outbuf[8192];

  lzma_stream strm = LZMA_STREAM_INIT;
  lzma_mt mt;
  memset(&mt, 0, sizeof(mt));
  mt.flags = LZMA_CONCATENATED;
  mt.threads = threads;
  mt.timeout = 0;
  mt.memlimit_threading = UINT64_MAX;
  mt.memlimit_stop = UINT64_MAX;

  lzma_ret ret = lzma_stream_decoder_mt(&strm, &mt);
  if (ret != LZMA_OK) {
    fprintf(stderr, "lzma_stream_decoder_mt: %u\n", ret);
    return 1;
  }

  lzma_action action = LZMA_RUN;
  strm.avail_in = 0;
  strm.next_in = NULL;

  do {
    if (strm.avail_in == 0 && action != LZMA_FINISH) {
      strm.next_in = inbuf;
      strm.avail_in = fread(inbuf, 1, sizeof(inbuf), in);
      if (ferror(in)) {
        fprintf(stderr, "read: %s\n", strerror(errno));
        lzma_end(&strm);
        return 1;
      }
      if (feof(in)) action = LZMA_FINISH;
    }

    strm.next_out = outbuf;
    strm.avail_out = sizeof(outbuf);
    ret = lzma_code(&strm, action);
    if (ret != LZMA_OK && ret != LZMA_STREAM_END) {
      fprintf(stderr, "lzma_code: %u\n", ret);
      lzma_end(&strm);
      return 1;
    }
  } while (ret != LZMA_STREAM_END);

  lzma_end(&strm);
  return 0;
}

int main(int argc, char **argv) {
  if (argc != 3 || argv[1][0] < '1' || argv[1][1] != '\0') {
    fprintf(stderr, "Usage: %s <threads> <file.xz>\n", argv[0]);
    return 1;
  }

  uint32_t threads = (uint32_t)(argv[1][0] - '0');
  FILE *in = fopen(argv[2], "rb");
  if (in == NULL) {
    fprintf(stderr, "open %s: %s\n", argv[2], strerror(errno));
    return 1;
  }

  int status = decode(in, threads);
  fclose(in);
  if (status == 0) puts("OK");
  return status;
}
